functions.Activities:
{
   if(!role.myTarget.isAlive)
   {
      role.myTarget = undefined;
   }
   if("使用技能中" == role.motion || !role.isAlive)
   {
      return undefined;
   }
   if("使用技能结束" == role.motion)
   {
      switch(role.skillEffect)
      {
         case "斩魂":
            role.斩魂效果();
            break;
         case "旋风斩":
            role.旋风斩效果();
            break;
         case "刀光斩":
            role.刀光斩效果();
            break;
         case "飞天连斩结束":
            role.飞天连斩结束();
            break;
         case "狂暴":
            role.狂暴效果();
            break;
         case "震":
            role.震效果();
            break;
         case "电击术":
            role.电击术效果();
            break;
         case "火球术":
            role.火球术效果();
            break;
         case "光辉光环":
            role.光辉光环效果();
            break;
         case "爆雷术":
            role.爆雷术效果();
            break;
         case "雷霆万钧":
            role.雷霆万钧效果();
            break;
         case "怒":
            role.怒效果();
            break;
         case "飞天一斩":
         case "飞天二斩":
         case "飞天三斩":
            role.飞天连斩效果();
            role.motion = "使用技能中";
            return undefined;
      }
      role.stopTime = role.attackStopTime;
      role.skillEffect = "无";
      role.站立();
   }
   else if(!this._parent.catchMouseDown && !Key.isDown(37) && !Key.isDown(39) && !Key.isDown(38) && !Key.isDown(40) && !Key.isDown(65) && !Key.isDown(68) && !Key.isDown(83) && !Key.isDown(87))
   {
      role.站立();
   }
   if(this.stopTime > 0)
   {
      this.stopTime = this.stopTime - 1;
      return false;
   }
   this.direct = this.turnDirection();
   if(role.cantMove != true)
   {
      if(Key.isDown(37) || Key.isDown(65) || this.direct == "左" || this.direct == "左上" || this.direct == "左下")
      {
         role.faceTo = "左";
         if(Key.isDown(38) || Key.isDown(87) || this.direct == "左上")
         {
            role.向左上跑();
         }
         else if(Key.isDown(40) || Key.isDown(83) || this.direct == "左下")
         {
            role.向左下跑();
         }
         else
         {
            role.向左跑();
         }
      }
      else if(Key.isDown(39) || Key.isDown(68) || this.direct == "右" || this.direct == "右上" || this.direct == "右下")
      {
         role.faceTo = "右";
         if(Key.isDown(38) || Key.isDown(87) || this.direct == "右上")
         {
            role.向右上跑();
         }
         else if(Key.isDown(40) || Key.isDown(83) || this.direct == "右下")
         {
            role.向右下跑();
         }
         else
         {
            role.向右跑();
         }
      }
      else if(Key.isDown(38) || Key.isDown(87) || this.direct == "上")
      {
         role.向上跑();
      }
      else if(Key.isDown(40) || Key.isDown(83) || this.direct == "下")
      {
         role.向下跑();
      }
   }
}

functions.turnDirection:
{
   var _loc3_;
   var _loc2_;
   var _loc4_;
   if(this._parent.catchMouseDown)
   {
      _loc3_ = this._parent._xmouse - this._x;
      _loc2_ = this._parent._ymouse - this._y;
      if(Math.abs(_loc3_) > this.speedX || Math.abs(_loc2_) > this.speedY)
      {
         _loc4_ = Math.abs(_loc3_) - Math.abs(_loc2_);
         if(_loc4_ > this.speedX)
         {
            return _loc3_ <= 0 ? "左" : "右";
         }
         if(_loc4_ < this.speedY)
         {
            return _loc2_ <= 0 ? "上" : "下";
         }
         if(_loc3_ > 0)
         {
            return _loc2_ <= 0 ? "右上" : "右下";
         }
         return _loc2_ <= 0 ? "左上" : "左下";
      }
   }
   return "";
}

functions.jumpMap:
{
   var _loc2_;
   _loc2_ = 1;
   while(_loc2_ <= 6)
   {
      if(this["entry" + _loc2_].hitTest(this.role._x,this.role._y,false) == true && this["entry" + _loc2_]._visible == true)
      {
         this.jumpToMap(this["entry" + _loc2_]);
         return true;
      }
      _loc2_ = _loc2_ + 1;
   }
   return false;
}

functions.jumpToMap:
{
   if(entry._alpha == 0)
   {
      return false;
   }
   entry1._visible = true;
   entry2._visible = true;
   entry3._visible = true;
   entry4._visible = true;
   entry5._visible = true;
   entry6._visible = true;
   switch(entry.toMap)
   {
      case "沼泽郊区":
         if(_parent.task.getTask("接应国王").isComplete != true)
         {
            _global.msg.open("\r\r\r前方有魔族军团，没有国王命令不能进入");
            return false;
         }
         break;
      case "冰封走廊":
         if(role.levels < 70)
         {
            _global.msg.open("\r\r\r前方有魔族军团，70级前不能进入");
            return false;
         }
         break;
      case "失落高地一":
         if(role.levels < 100)
         {
            _global.msg.open("\r\r\r100级前不能进入");
            return false;
         }
   }
   if(entry)
   {
      this.nextMap = entry.toMap;
      this.nextEntry = entry.toEntry;
      this.role.myTarget = undefined;
      this.huanShou1.myTarget = undefined;
      this.huanShou2.myTarget = undefined;
      this.huanShou3.myTarget = undefined;
      this.gotoAndStop(this.nextMap);
      return true;
   }
   return false;
}

functions.allowJumpMap:
{
   if(this.nextMap == toMap)
   {
      this.goods.clearGoods();
      this._parent.closeAllPanel();
      this._parent.warning.close();
      this.nowMap = this.nextMap;
      this.afterJumpMap(this.nowMap);
      return true;
   }
   this.nextMap = this.nowMap;
   this.gotoAndStop(this.nowMap);
   return false;
}

functions.afterJumpMap:
{
   var _loc4_;
   var _loc3_;
   if(nextEntry != undefined)
   {
      _loc4_ = this[nextEntry]._x;
      _loc3_ = this[nextEntry]._y;
      this.role._x = _loc4_;
      this.role._y = _loc3_;
      this.huanShou1._x = _loc4_ - 15;
      this.huanShou1._y = _loc3_ - 15;
      this.huanShou2._x = _loc4_ + 5;
      this.huanShou2._y = _loc3_ + 5;
      this.huanShou3._x = _loc4_ + 20;
      this.huanShou3._y = _loc3_ + 20;
   }
   this.nextMap = "";
   this.nextEntry = "";
   _global.ownMap = false;
   this.hideMonster();
   this.hideNPC();
   if(nowMap != "冰宫郊区")
   {
      this.冰柱._visible = false;
   }
   return true;
}
